from __future__ import annotations

from datetime import datetime
from pathlib import Path

from src.strategies.base_strategy import BaseStrategy
from src.strategies.registry import registry

_EXPORT_DIR = Path(__file__).parents[2] / "exports" / "thinkscript"

_GENERIC_TEMPLATE = """\
# {strategy_name} — Generic Signal Template
# Generated by day-trading-platform on {date}

def entrySignal = /* strategy entry condition */;
def exitSignal  = /* strategy exit condition */;

Alert(entrySignal, "{strategy_name} Entry", Alert.BAR, Sound.Chime);
Alert(exitSignal,  "{strategy_name} Exit",  Alert.BAR, Sound.Ring);
AddChartBubble(entrySignal, low,  "\\u25B2", Color.GREEN, no);
AddChartBubble(exitSignal,  high, "\\u25BC", Color.RED,   yes);
"""

_STUDY_HEADER = """\
# {strategy_name} Strategy
# Generated by day-trading-platform on {date}
# Paste into TOS: Studies → Edit Studies → New Study → paste → Save

declare upper;

"""


def export(strategy_name: str, params: dict | None = None) -> Path:
    """Export ThinkScript for a strategy and return the output file path."""
    strat: BaseStrategy = registry.build(strategy_name, params=params)
    body = strat.thinkscript_body()

    date_str = datetime.now().strftime("%Y%m%d")
    header = _STUDY_HEADER.format(strategy_name=strategy_name, date=date_str)

    if not body:
        body = _GENERIC_TEMPLATE.format(strategy_name=strategy_name, date=date_str)

    content = header + body

    _EXPORT_DIR.mkdir(parents=True, exist_ok=True)
    out_path = _EXPORT_DIR / f"{strategy_name}_{date_str}.ts"
    out_path.write_text(content, encoding="utf-8")
    return out_path


def export_all(params_map: dict[str, dict] | None = None) -> list[Path]:
    """Export ThinkScript files for every registered strategy."""
    params_map = params_map or {}
    return [export(name, params=params_map.get(name)) for name in registry.list()]
